            var body=new StackPanel();body.Children.Add(new TextBlock {Text="安装、升级与回退",FontSize=25,FontWeight=FontWeights.SemiBold,Margin=new Thickness(0,0,0,12)});body.Children.Add(new TextBlock {Text="先从托盘退出使用同一数据的工作台。选择已解压的完整发行包，程序会验证受信签名及全部文件。不会自动启动 QQ 或调用模型。",TextWrapping=TextWrapping.Wrap,LineHeight=21});
