            body.Children.Add(new TextBlock {Text="程序和数据须使用独立目录。升级前保留加密恢复点，检查失败撤回程序切换。新版本已经产生数据时拒绝旧快照自动覆盖。回退时输入对应恢复点密码，中断处理不需要密码。",TextWrapping=TextWrapping.Wrap,LineHeight=21,Foreground=Ink("#64748B"),Margin=new Thickness(0,14,0,14)});
            var buttons=new WrapPanel();foreach(var pair in new[]{new[]{"安装或升级","install"},new[]{"修复当前版本","repair"},new[]{"回退上一版本","rollback"},new[]{"处理上次中断","recover"},new[]{"卸载程序，保留数据","uninstall"}}){string operation=pair[1];var button=new Button {Content=pair[0],MinHeight=36,Padding=new Thickness(12,3,12,3),Margin=new Thickness(0,0,10,10)};button.Click+=(s,e)=>Begin(operation);buttons.Children.Add(button);actions.Add(button);}body.Children.Add(buttons);
