            var dock=new DockPanel();DockPanel.SetDock(footer,Dock.Bottom);dock.Children.Add(footer);var result=new ScrollViewer {Content=status,MaxHeight=140,VerticalScrollBarVisibility=ScrollBarVisibility.Auto};DockPanel.SetDock(result,Dock.Bottom);dock.Children.Add(result);var scroll=new ScrollViewer {Content=body,VerticalScrollBarVisibility=ScrollBarVisibility.Auto,HorizontalScrollBarVisibility=ScrollBarVisibility.Disabled,HorizontalContentAlignment=HorizontalAlignment.Stretch};body.SetBinding(FrameworkElement.WidthProperty,new System.Windows.Data.Binding("ViewportWidth"){Source=scroll});dock.Children.Add(scroll);window.Content=new Border {Padding=new Thickness(26),Background=window.Background,Child=dock};window.Closing+=(s,e)=>{if(busy){e.Cancel=true;status.Text="操作尚未收尾，请取消并等待结果后关闭。";}else{password.Clear();confirmation.Clear();}};
