    static void SetBusy(bool value){busy=value;foreach(var button in actions)button.IsEnabled=!value;package.IsEnabled=install.IsEnabled=data.IsEnabled=password.IsEnabled=confirmation.IsEnabled=!value;cancel.IsEnabled=value;}
    static void Begin(string operation){
