        if(operation=="uninstall"&&smokeRequest==null){if(uninstallMode!="confirmed"&&MessageBox.Show(window,"卸载程序和启动入口，聊天、配置、密钥及备份全部保留在数据目录。是否继续？","确认卸载",MessageBoxButton.YesNo,MessageBoxImage.Warning)!=MessageBoxResult.Yes)return;string target=Path.GetFullPath(install.Text).TrimEnd(Path.DirectorySeparatorChar);if(root.StartsWith(target+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase)){SetBusy(true);status.Text="正在准备独立卸载工具，请稍候…";string temporary=Path.Combine(Path.GetTempPath(),"whale-uninstall-"+Guid.NewGuid().ToString("N")),selectedData=data.Text;ThreadPool.QueueUserWorkItem(_=>{try{PackageTrust.CopyVerified(root,temporary);window.Dispatcher.Invoke(new Action(()=>{Process.Start(new ProcessStartInfo(Path.Combine(temporary,"WhaleSetup.exe"),"--install-dir \""+target+"\" --data-dir \""+selectedData+"\" --uninstall-mode confirmed"){UseShellExecute=false,CreateNoWindow=true,WorkingDirectory=temporary});SetBusy(false);window.Close();}));}catch(Exception error){window.Dispatcher.Invoke(new Action(()=>Finish(false,error.Message,null)));}});return;}}
        if(smokeRequest==null&&operation=="rollback"&&MessageBox.Show(window,"仅在数据未改变且恢复点可验证时切回上一程序版本，是否继续？","确认回退",MessageBoxButton.YesNo,MessageBoxImage.Warning)!=MessageBoxResult.Yes)return;
        var request=new Dictionary<string,object>{{"operation",operation},{"packageRoot",package.Text},{"installRoot",install.Text},{"dataRoot",data.Text},{"password",password.Password}};SetBusy(true);cancelled=false;replied=false;status.Text="正在校验安装工具与发行文件…";
