    static void Receive(Dictionary<string,object> message,string operation){
        if(Convert.ToString(message["type"])=="progress"){string stage=Convert.ToString(message["stage"]);status.Text=stage=="recovery-point"?"正在保存当前数据的加密恢复点…":stage=="install-check"?"正在检查新版本，业务尚未启动…":"正在验证发行文件："+(message.ContainsKey("files")?Convert.ToString(message["files"]):"0");return;}
        if(Convert.ToString(message["type"])!="result")return;bool ok=Convert.ToBoolean(message["ok"]);string text=ok?"操作完成。程序和数据已保留在所选目录；请从安装启动器打开工作台。":Convert.ToString(message["error"]);var result=ok?(Dictionary<string,object>)message["result"]:null;if(result!=null&&result.ContainsKey("installRoot"))install.Text=Convert.ToString(result["installRoot"]);if(result!=null&&result.ContainsKey("dataRoot"))data.Text=Convert.ToString(result["dataRoot"]);
