        if(ok&&operation=="uninstall"){text="程序已卸载，数据与加密恢复点已保留。";RemoveBindings(install.Text);if(result!=null&&result["retiredDirectory"]!=null)text+="\n无法确认或仍占用的文件保留在："+Convert.ToString(result["retiredDirectory"]);}
