    static void CreateShortcut(string directory){directory=Path.GetFullPath(directory).TrimEnd(Path.DirectorySeparatorChar,Path.AltDirectorySeparatorChar);Directory.CreateDirectory(Path.GetDirectoryName(ShortcutPath));var shell=Activator.CreateInstance(Type.GetTypeFromProgID("WScript.Shell"));var shortcut=shell.GetType().InvokeMember("CreateShortcut",System.Reflection.BindingFlags.InvokeMethod,null,shell,new object[]{ShortcutPath});var type=shortcut.GetType();type.InvokeMember("TargetPath",System.Reflection.BindingFlags.SetProperty,null,shortcut,new object[]{Path.Combine(directory,"WhaleLauncher.exe")});type.InvokeMember("WorkingDirectory",System.Reflection.BindingFlags.SetProperty,null,shortcut,new object[]{directory});type.InvokeMember("Save",System.Reflection.BindingFlags.InvokeMethod,null,shortcut,null);}
    static void RegisterInstallation(string directory){directory=Path.GetFullPath(directory).TrimEnd(Path.DirectorySeparatorChar,Path.AltDirectorySeparatorChar);var state=PackageTrust.Object(PackageTrust.Read(Path.Combine(directory,"install-state.json"),131072));var current=(Dictionary<string,object>)state["current"];using(var key=Microsoft.Win32.Registry.CurrentUser.CreateSubKey(BindingRegistryPath)){key.SetValue("DisplayName","小鲸工作台");key.SetValue("DisplayVersion",Convert.ToString(current["version"]));key.SetValue("InstallLocation",directory);key.SetValue("UninstallString","\""+Path.Combine(directory,"WhaleSetup.exe")+"\" --uninstall-mode ask");key.SetValue("NoModify",1);key.SetValue("NoRepair",1);}}
    static void RemoveBindings(string directory){try{directory=Path.GetFullPath(directory).TrimEnd(Path.DirectorySeparatorChar,Path.AltDirectorySeparatorChar);using(var key=Microsoft.Win32.Registry.CurrentUser.OpenSubKey(BindingRegistryPath)){if(key==null||!String.Equals(Convert.ToString(key.GetValue("InstallLocation")),directory,StringComparison.OrdinalIgnoreCase))return;}Microsoft.Win32.Registry.CurrentUser.DeleteSubKeyTree(BindingRegistryPath,false);string path=ShortcutPath;if(File.Exists(path)){var shell=Activator.CreateInstance(Type.GetTypeFromProgID("WScript.Shell"));var shortcut=shell.GetType().InvokeMember("CreateShortcut",System.Reflection.BindingFlags.InvokeMethod,null,shell,new object[]{path});string target=Convert.ToString(shortcut.GetType().InvokeMember("TargetPath",System.Reflection.BindingFlags.GetProperty,null,shortcut,null));if(String.Equals(Path.GetFullPath(target),Path.Combine(directory,"WhaleLauncher.exe"),StringComparison.OrdinalIgnoreCase))File.Delete(path);}}catch{}}
    static bool BindingExists(){using(var key=Microsoft.Win32.Registry.CurrentUser.OpenSubKey(BindingRegistryPath))return key!=null;}
    static void Finish(bool ok,string text,Dictionary<string,object> result){replied=true;SetBusy(false);password.Clear();confirmation.Clear();status.Text=text;if(smokeRequest!=null){File.WriteAllText(Path.Combine(Path.GetDirectoryName(smokeFile),"setup-smoke-result.json"),PackageTrust.Serialize(new {ok=ok,text=text,result=result,bindings=new {registered=BindingExists(),shortcut=File.Exists(ShortcutPath)}}),new UTF8Encoding(false));Capture(Path.Combine(Path.GetDirectoryName(smokeFile),"setup-smoke.png"));window.Close();}}
    static void Capture(string path){window.UpdateLayout();var content=(FrameworkElement)window.Content;var bitmap=new RenderTargetBitmap((int)content.ActualWidth,(int)content.ActualHeight,96,96,PixelFormats.Pbgra32);bitmap.Render(content);var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(bitmap));using(var stream=File.Create(path))encoder.Save(stream);}
    static void RunSmoke(){package.Text=Convert.ToString(smokeRequest["packageRoot"]);install.Text=Convert.ToString(smokeRequest["installRoot"]);data.Text=Convert.ToString(smokeRequest["dataRoot"]);password.Password=smokeRequest.ContainsKey("password")?Convert.ToString(smokeRequest["password"]):"";confirmation.Password=password.Password;if(Convert.ToString(smokeRequest["operation"])=="bindings"){try{CreateShortcut(install.Text);RegisterInstallation(install.Text);if(!BindingExists()||!File.Exists(ShortcutPath))throw new Exception("安装入口未创建");RemoveBindings(install.Text);if(BindingExists()||File.Exists(ShortcutPath))throw new Exception("卸载入口未清理");Finish(true,"独立注册表测试键与临时快捷方式检查通过。",null);}catch(Exception error){RemoveBindings(install.Text);Finish(false,error.Message,null);}return;}if(Convert.ToString(smokeRequest["operation"])=="layout"){window.Width=500;window.Height=580;SetBusy(true);if(actions[0].IsEnabled||!cancel.IsEnabled)throw new Exception("安装控件互斥失败");window.UpdateLayout();foreach(var button in new[]{cancel,close})if(button.TranslatePoint(new Point(0,button.ActualHeight),(UIElement)window.Content).Y>((FrameworkElement)window.Content).ActualHeight)throw new Exception("安装取消动作被遮挡");Finish(true,"安装工具紧凑布局与取消入口检查通过。",null);return;}Begin(Convert.ToString(smokeRequest["operation"]));}
